package dev.annawathe.client.mixin;
import dev.annawathe.client.gui.AnnaStoreRenderer; import dev.doctor4t.wathe.client.gui.StoreRenderer; import net.minecraft.client.font.TextRenderer; import net.minecraft.client.gui.DrawContext; import net.minecraft.client.network.ClientPlayerEntity; import org.spongepowered.asm.mixin.Mixin; import org.spongepowered.asm.mixin.injection.At; import org.spongepowered.asm.mixin.injection.Inject; import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
@Mixin(StoreRenderer.class) public abstract class StoreRendererMixin { @Inject(method="renderHud",at=@At("HEAD"),cancellable=true) private static void annawathe$render(TextRenderer r,ClientPlayerEntity p,DrawContext c,float d,CallbackInfo ci){AnnaStoreRenderer.renderHud(r,p,c,d);ci.cancel();} @Inject(method="tick",at=@At("HEAD"),cancellable=true) private static void annawathe$tick(CallbackInfo ci){AnnaStoreRenderer.tick();ci.cancel();} }
